const inputData = $('Execute Workflow Trigger').first()?.json || {};
const fechaInicio = inputData.fecha_inicio || '2026-10-01';
const fechaFin = inputData.fecha_fin || '2026-11-01';

const declaraciones = $('Obtener Declaraciones').all().map(i => i.json);
const importadores = $('Obtener Importadores').all().map(i => i.json);
const agentes = $('Obtener Agentes Aduanales').all().map(i => i.json);

const impMap = new Map(importadores.map(imp => [imp.id_importador, imp.razon_social]));
const ageMap = new Map(agentes.map(age => [age.id_agente_aduanal, age.nombre_completo]));

const filtradas = declaraciones
  .filter(d => d.regimen === 'Importacion' && d.fecha_declaracion >= fechaInicio && d.fecha_declaracion < fechaFin)
  .map(d => ({
    numero_dua: d.numero_dua,
    fecha_declaracion: d.fecha_declaracion,
    importador: impMap.get(d.id_importador) || 'Desconocido',
    agente_aduanal: ageMap.get(d.id_agente_aduanal) || 'Desconocido',
    regimen: d.regimen,
    estado_operativo: d.estado,
    moneda: d.moneda
  }))
  .sort((a, b) => a.fecha_declaracion.localeCompare(b.fecha_declaracion) || a.numero_dua.localeCompare(b.numero_dua));

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_importaciones_periodo',
    filtros: { regimen: 'Importacion', fecha_inicio: fechaInicio, fecha_fin: fechaFin },
    total_registros: filtradas.length,
    es_parcial: false,
    datos: filtradas
  }
}];
